import * as React from "react";

export type PauseSquareIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function PauseSquareIcon({ size = 20, ...props }: PauseSquareIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="16" rx="2" /><path d="M9.8 8.5v7M14.2 8.5v7" />
    </svg>
  );
}
